<?php echo form_open(admin_url('sales_delivery_flow/create_return/'.$invoice->id));?><h4>اقلام تحویل‌شده / قابل مرجوعی</h4><table class="table table-bordered"><thead><tr><th>شرح کالا</th><th>تحویل‌شده</th><th>مرجوعی قبلی</th><th>قابل مرجوعی</th><th>قیمت واحد</th><th style="width:180px">تعداد مرجوعی</th></tr></thead><tbody><?php foreach($return_items as $it){?><tr><td><?php echo html_escape($it['description']??'');?></td><td><?php echo (float)$it['delivered_qty'];?></td><td><?php echo (float)$it['returned_qty'];?></td><td><b><?php echo (float)$it['returnable_qty'];?></b></td><td><?php echo app_format_money($it['rate']??0,'');?></td><td><input class="form-control sdf-rqty" type="number" min="0" step="0.01" max="<?php echo (float)$it['returnable_qty'];?>" name="return_qty[<?php echo (int)$it['itemable_id'];?>]" value="0" data-max="<?php echo (float)$it['returnable_qty'];?>" <?php echo $it['returnable_qty']<=0?'disabled':'';?>></td></tr><?php }?></tbody></table><p><button type="button" id="sdf-return-all" class="btn btn-default"><i class="fa fa-check-square-o"></i> مرجوعی کامل باقیمانده فاکتور</button></p><div class="row"><div class="col-md-6"><?php echo render_input('reason','علت مرجوعی');?></div><div class="col-md-6"><?php echo render_textarea('note','توضیحات / وضعیت کالا هنگام برگشت');?></div></div><button class="btn btn-danger" type="submit" onclick="return confirm('مرجوعی ثبت شود و موجودی اقلام انتخاب‌شده به انبار برگردد؟');"><i class="fa fa-undo"></i> ثبت مرجوعی و ورود مجدد به انبار</button><?php echo form_close();?><hr>
<h4>سوابق مرجوعی این فاکتور</h4><?php if(!$returns){?><p class="text-muted">هنوز مرجوعی ثبت نشده است.</p><?php }else{?><table class="table"><thead><tr><th>شماره مرجوعی</th><th>تاریخ</th><th>مبلغ اقلام</th><th>علت</th><th>رسید</th></tr></thead><tbody><?php foreach($returns as $r){?><tr><td><?php echo html_escape($r['return_no']);?></td><td><?php echo html_escape($r['return_date']);?></td><td><?php echo app_format_money($r['total_amount'],'');?></td><td><?php echo html_escape($r['reason']?:'-');?></td><td><a target="_blank" class="btn btn-default btn-xs" href="<?php echo admin_url('sales_delivery_flow/print_return/'.$invoice->id.'/'.$r['id']);?>"><i class="fa fa-print"></i> چاپ رسید</a></td></tr><?php }?></tbody></table><?php }?></div></div></div></div><script>document.addEventListener('DOMContentLoaded',function(){var b=document.getElementById('sdf-return-all');if(b)b.onclick=function(){document.querySelectorAll('.sdf-rqty:not([disabled])').forEach(function(x){x.value=x.getAttribute('data-max')||0;});};});</script><?php init_tail(); ?>
